      faq: {
        id: 'faq',
        title: 'Frequently Asked Questions',
        faqs: [
          {
            q: 'Which is better for local coding in 2026, DeepSeek or Qwen?',
            a: 'The published numbers do not settle it, because the vendors report different benchmark versions and harnesses. As published by Qwen, Qwen3.8-27B scores 61.7 on SWE-bench Pro, 73.0 on Terminal-Bench 2.1 (Terminus harness) and 90.3 on LiveCodeBench v6. As published by DeepSeek, DeepSeek-V4.1-Flash scores 90.6 on Terminal-Bench 2.1 and 74.2 on DeepSWE v1.1 under DeepSeek\'s own maximum-reasoning-effort setup. For code that must stay on your machine, only the Qwen model has an official consumer-size build (Ollama: 18 GB at Q4_K_M).',
          },
          {
            q: 'Can I run DeepSeek-V4 locally?',
            a: 'The weights are open (MIT licence) but not consumer-sized. Hugging Face file sizes: V4-Flash (Preview) 159.6 GB, V4-Flash-0731 166.9 GB, V4.1-Flash 510.3 GB, V4-Pro-0813 892.7 GB. Divided by 24 GB, that is 6.7 to 37.2 cards of 24 GB for the weights alone, before the KV cache. Ollama\'s official deepseek-v4-pro and deepseek-v4.1-flash entries list cloud tags only (checked 2026-10-20). Realistic routes are server hardware you control, a rented server, or the DeepSeek API.',
          },
          {
            q: 'What does Qwen3.8-27B need to run locally?',
            a: 'Ollama lists qwen3.8:27b at 18 GB (Q4_K_M, 256K context window), 30 GB at Q8_0 and 56 GB at BF16. On a 24 GB card the 18 GB build leaves about 6 GB for the context cache and runtime; on a 16 GB card it does not fit in VRAM. We have not measured speed or maximum context on any card, so this page gives no tokens-per-second figure.',
          },
          {
            q: 'Are the benchmark numbers on this page comparable?',
            a: 'Only within the same benchmark version and harness. Terminal-Bench 2.0, 2.1 and 4.0 are different versions, SWE-bench Verified and Pro are different task sets, and each vendor used its own harness, reasoning effort and sampling. Treat the table as a record of what each vendor published, not a head-to-head. PromptQuorum has not run any of these benchmarks.',
          },
          {
            q: 'How does the DeepSeek API compare in cost with running Qwen locally?',
            a: 'We do not quote API prices here because they change; see [DeepSeek\'s pricing page](https://api-docs.deepseek.com/quick_start/pricing) for current rates (Ollama\'s cloud listing for deepseek-v4.1-flash shows its own per-token rates). A local setup has no per-token fee but costs hardware and electricity. The main reason to run locally is that inference stays on your machine instead of going to a vendor\'s cloud API (check your tools\' telemetry settings), not that it is cheaper.',
          },
          {
            q: 'Are DeepSeek-V3, R1 and Qwen2.5-Coder still current?',
            a: 'No. They are the previous generation and appear only in the history section. DeepSeek\'s API names deepseek-chat and deepseek-reasoner (V3/R1 era) were scheduled for retirement on 2026-07-24. The current open generations are DeepSeek V4 / V4.1 and Qwen3.8; for the 35B-A3B MoE size we found no Qwen3.8 successor in Qwen\'s Hugging Face listing, so Qwen3.6-35B-A3B is shown.',
          },
        ],
      },
