          '2026-10-20: Reconstruida en torno a la generación actual. Se sustituyó el veredicto de la generación anterior por cifras publicadas por los proveedores para Qwen3.8-27B, Qwen3.8-Flash-Next, Qwen3.6 y DeepSeek V4 (Preview, V4-Flash-0731, V4-Pro-0813, V4.1-Flash y V4.1-Flash-1017) a partir de las fichas de modelo de Hugging Face, más los tamaños de pesos (Hugging Face) y de etiquetas de Ollama, todo comprobado el 2026-10-20. Se eliminaron la tabla de velocidad sin medir y los ganadores editoriales por lenguaje; la comparación Qwen2.5-Coder / DeepSeek-V3 pasó a una sección de historial; la pregunta frecuente de la API basada en precios se sustituyó por una sin precios; el enlace de afiliado de GPU ahora apunta a una búsqueda de RTX 4090 24 GB.',
