    faqSchema: {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      mainEntity: [
        {
          '@type': 'Question',
          name: '¿Qué es mejor para coding local en 2026, DeepSeek o Qwen?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Las cifras publicadas no lo resuelven, porque cada proveedor usa otras versiones de benchmark y otros harnesses. Según lo publicado por Qwen, Qwen3.8-27B obtiene 61.7 en SWE-bench Pro, 73.0 en Terminal-Bench 2.1 (harness Terminus) y 90.3 en LiveCodeBench v6. Según lo publicado por DeepSeek, DeepSeek-V4.1-Flash obtiene 90.6 en Terminal-Bench 2.1 y 74.2 en DeepSWE v1.1 con la configuración propia de DeepSeek de máximo esfuerzo de razonamiento. Para código que debe quedarse en tu equipo, solo el modelo de Qwen tiene una versión oficial de tamaño de consumo (Ollama: 18 GB en Q4_K_M).',
          },
        },
        {
          '@type': 'Question',
          name: '¿Puedo ejecutar DeepSeek-V4 en local?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Los pesos son abiertos (licencia MIT), pero no de tamaño de consumo. Tamaños de archivo en Hugging Face: V4-Flash (Preview) 159.6 GB, V4-Flash-0731 166.9 GB, V4.1-Flash 510.3 GB, V4-Pro-0813 892.7 GB. Divididos entre 24 GB, son de 6.7 a 37.2 tarjetas de 24 GB solo para los pesos, antes de la caché KV. Las entradas oficiales deepseek-v4-pro y deepseek-v4.1-flash de Ollama solo listan etiquetas en la nube (comprobado el 2026-10-20). Las vías realistas son hardware de servidor que controles, un servidor alquilado o la API de DeepSeek.',
          },
        },
        {
          '@type': 'Question',
          name: '¿Qué necesita Qwen3.8-27B para ejecutarse en local?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Ollama lista qwen3.8:27b en 18 GB (Q4_K_M, ventana de contexto de 256K), 30 GB en Q8_0 y 56 GB en BF16. En una tarjeta de 24 GB, la versión de 18 GB deja unos 6 GB para la caché de contexto y el runtime; en una de 16 GB no cabe en VRAM. No hemos medido velocidad ni contexto máximo en ninguna tarjeta, así que esta página no da cifras de tokens por segundo.',
          },
        },
        {
          '@type': 'Question',
          name: '¿Son comparables las cifras de benchmarks de esta página?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Solo dentro de la misma versión de benchmark y el mismo harness. Terminal-Bench 2.0, 2.1 y 4.0 son versiones distintas, SWE-bench Verified y Pro son conjuntos de tareas distintos, y cada proveedor usó su propio harness, esfuerzo de razonamiento y muestreo. Trata la tabla como un registro de lo que publicó cada proveedor, no como un cara a cara. PromptQuorum no ha ejecutado ninguno de estos benchmarks.',
          },
        },
        {
          '@type': 'Question',
          name: '¿Cómo se compara el coste de la API de DeepSeek con ejecutar Qwen en local?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Aquí no citamos precios de API porque cambian; consulta la [página de precios de DeepSeek](https://api-docs.deepseek.com/quick_start/pricing) para las tarifas vigentes (el listado cloud de Ollama para deepseek-v4.1-flash muestra sus propias tarifas por token). Una configuración local no tiene coste por token, pero cuesta hardware y electricidad. El motivo principal para ejecutar en local es que la inferencia se queda en tu equipo en lugar de ir a la API en la nube de un proveedor (revisa la telemetría de tus herramientas), no que sea más barato.',
          },
        },
        {
          '@type': 'Question',
          name: '¿Siguen vigentes DeepSeek-V3, R1 y Qwen2.5-Coder?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'No. Son la generación anterior y aparecen solo en la sección de historial. Los nombres de API deepseek-chat y deepseek-reasoner de DeepSeek (era V3/R1) estaban programados para retirarse el 2026-07-24. Las generaciones abiertas actuales son DeepSeek V4 / V4.1 y Qwen3.8; para el tamaño MoE 35B-A3B no encontramos un sucesor Qwen3.8 en el listado de Qwen en Hugging Face, por eso se muestra Qwen3.6-35B-A3B.',
          },
        },
      ],
    },
