        title: 'Wichtigste Erkenntnisse',
        items: [
          'Diese Seite verwendet ausschließlich Werte, die die Hersteller auf ihren eigenen Model Cards veröffentlicht haben; PromptQuorum hat keinen Benchmark selbst ausgeführt. Da sich Versionen und Harnesses unterscheiden, sind die Zeilen kein direkter Vergleich.',
          'Qwen3.8-27B ist das aktuelle, lokal taugliche Qwen: Apache-2.0, 27B dicht, 55,6 GB in BF16 auf Hugging Face und 18 GB im Q4_K_M-Build von Ollama. Auf einer 24-GB-Karte bleiben damit etwa 6 GB (24 minus 18) für Kontext-Cache und Laufzeit.',
          'DeepSeeks aktuelle offene Gewichte (V4-Flash, V4-Flash-0731, V4.1-Flash, V4-Pro-0813) stehen unter MIT-Lizenz, benötigen aber allein für die Gewichte 159,6 bis 892,7 GB – das 6,7- bis 37,2-Fache einer 24-GB-Karte.',
          'Die offiziellen Ollama-Einträge deepseek-v4-pro und deepseek-v4.1-flash führen nur Cloud-Tags; bei der Prüfung am 2026-10-20 war kein lokaler Download-Tag gelistet.',
          'Laut Veröffentlichung von DeepSeek erreicht V4.1-Flash 90,6 bei Terminal-Bench 2.1 und 74,2 bei DeepSWE v1.1; laut Veröffentlichung von Qwen erreicht Qwen3.8-27B 73,0 und 42,2 im eigenen Harness. Ziehen Sie die Werte nicht voneinander ab.',
          'Qwen2.5-Coder, DeepSeek-V3 und DeepSeek-R1 sind die Vorgängergeneration; ihre älteren HumanEval- und LiveCodeBench-Werte stehen nur noch in einem Historienabschnitt.',
        ],
