            type: 'one-sentence',
            text: 'Qwen3.8-27B (Apache-2.0, 18 GB bei Ollama mit Q4_K_M) ist das aktuelle Modell dieses Paares, das auf eine 24-GB-GPU passt, während DeepSeek V4 (MIT, 160 bis 893 GB Gewichte) Server-Klasse ist; die von den Herstellern veröffentlichten Coding-Benchmarks nutzen unterschiedliche Setups und lassen sich nicht gegeneinander ranken.',
