            text: 'Wenn Ihr Code Ihren Rechner nicht verlassen darf, nutzen Sie Qwen3.8-27B: Es ist klein genug für eine Grafikkarte mit 24 GB. DeepSeek V4 ist ebenfalls offen, aber für einen normalen PC viel zu groß – die meisten greifen deshalb über einen Cloud-Dienst darauf zu. Die Testwerte der Unternehmen werden unterschiedlich gemessen und sagen daher nicht, welches Modell besser ist.',
