        note: 'Quellen (Hugging-Face-Model-Cards, geprüft am 2026-10-20): [Qwen3.8-27B](https://huggingface.co/Qwen/Qwen3.8-27B), [Qwen3.8-Flash-Next](https://huggingface.co/Qwen/Qwen3.8-Flash-Next), [Qwen3.6-27B](https://huggingface.co/Qwen/Qwen3.6-27B), [Qwen3.6-35B-A3B](https://huggingface.co/Qwen/Qwen3.6-35B-A3B), [DeepSeek-V4.1-Flash](https://huggingface.co/deepseek-ai/DeepSeek-V4.1-Flash), [V4.1-Flash-1017](https://huggingface.co/deepseek-ai/DeepSeek-V4.1-Flash-1017), [V4-Pro-0813](https://huggingface.co/deepseek-ai/DeepSeek-V4-Pro-0813), [V4-Flash-0731](https://huggingface.co/deepseek-ai/DeepSeek-V4-Flash-0731), [V4-Flash](https://huggingface.co/deepseek-ai/DeepSeek-V4-Flash), [V4-Pro](https://huggingface.co/deepseek-ai/DeepSeek-V4-Pro). Die Setups unterscheiden sich. Qwen3.8-27B: Terminal-Bench 2.1 mit dem Terminus-Harness, SWE-bench Pro auf einem bereinigten Aufgabensatz mit dem Claude-Code-Harness. Qwen3.6: Terminal-Bench 2.0 mit 3 Stunden Zeitlimit und Mittel aus 5 Läufen. DeepSeek V4.1-Flash und V4-Pro-0813: maximaler Reasoning-Aufwand (DeepSWE bei V4.1-Flash mit dem mini-SWE-Harness; V4-Pro-0813 mit DeepSeek Harness im Minimalmodus); die Zeile V4.1-Flash-1017 ist Terminal-Bench 4.0 mit dem Claude-Code-Harness; die Preview-Zeilen nutzen den maximalen Reasoning-Modus und nennen die LiveCodeBench-Version nicht. Terminal-Bench 2.0, 2.1 und 4.0 sind verschiedene Versionen mit unterschiedlicher Punkteskala, und SWE-bench Verified und Pro sind unterschiedliche Aufgabensätze. Die Karten von V4.1 und V4-0813 führen weder LiveCodeBench noch SWE-bench auf.',
