            a: 'いいえ。旧世代であり、履歴としてのみ残しています。旧世代のHumanEvalとLiveCodeBenchの数値（Qwen2.5-Coder 32B、DeepSeek-Coder-V2、DeepSeek-R1-Distill-Qwen-32B）は上記の数値と比較できません。APIネームdeepseek-chatとdeepseek-reasoner（V3/R1時代）は2026-07-24に終了予定でした。現行のオープン世代はDeepSeek V4 / V4.1とQwen3.8です。35B-A3Bサイズ（MoE）についてはHugging FaceのQwen一覧にQwen3.8の後継が見つからなかったため、Qwen3.6-35B-A3Bを掲載しています。',
