      faq: {
        id: 'faq',
        title: 'Perguntas frequentes',
        faqs: [
          {
            q: 'Qual é melhor para codificação local em 2026, DeepSeek ou Qwen?',
            a: 'Os números publicados não resolvem a questão, porque cada fornecedor usa versões de benchmark e harnesses diferentes. Conforme publicado pela Qwen, o Qwen3.8-27B marca 61.7 no SWE-bench Pro, 73.0 no Terminal-Bench 2.1 (harness Terminus) e 90.3 no LiveCodeBench v6. Conforme publicado pela DeepSeek, o DeepSeek-V4.1-Flash marca 90.6 no Terminal-Bench 2.1 e 74.2 no DeepSWE v1.1 na configuração própria da DeepSeek de esforço máximo de raciocínio. Para código que precisa ficar no seu computador, só o modelo da Qwen tem uma versão oficial de tamanho para consumidor (Ollama: 18 GB em Q4_K_M).',
          },
          {
            q: 'Posso rodar o DeepSeek-V4 localmente?',
            a: 'Os pesos são abertos (licença MIT), mas não têm tamanho de consumidor. Tamanhos de arquivo no Hugging Face: V4-Flash (Preview) 159.6 GB, V4-Flash-0731 166.9 GB, V4.1-Flash 510.3 GB, V4-Pro-0813 892.7 GB. Divididos por 24 GB, são de 6.7 a 37.2 placas de 24 GB só para os pesos, antes do cache KV. As entradas oficiais deepseek-v4-pro e deepseek-v4.1-flash do Ollama listam apenas tags na nuvem (verificado em 2026-10-20). Os caminhos realistas são hardware de servidor sob seu controle, um servidor alugado ou a API da DeepSeek.',
          },
          {
            q: 'O que o Qwen3.8-27B precisa para rodar localmente?',
            a: 'O Ollama lista o qwen3.8:27b com 18 GB (Q4_K_M, janela de contexto de 256K), 30 GB em Q8_0 e 56 GB em BF16. Em uma placa de 24 GB, a versão de 18 GB deixa cerca de 6 GB para o cache de contexto e o runtime; em uma de 16 GB ela não cabe na VRAM. Não medimos velocidade nem contexto máximo em nenhuma placa, então esta página não traz valores de tokens por segundo.',
          },
          {
            q: 'Os números de benchmark desta página são comparáveis?',
            a: 'Somente dentro da mesma versão de benchmark e do mesmo harness. Terminal-Bench 2.0, 2.1 e 4.0 são versões diferentes, SWE-bench Verified e Pro são conjuntos de tarefas diferentes, e cada fornecedor usou seu próprio harness, esforço de raciocínio e amostragem. Trate a tabela como um registro do que cada fornecedor publicou, não como um confronto direto. A PromptQuorum não executou nenhum desses benchmarks.',
          },
          {
            q: 'Como o custo da API da DeepSeek se compara a rodar o Qwen localmente?',
            a: 'Não citamos preços de API aqui porque eles mudam; consulte a [página de preços da DeepSeek](https://api-docs.deepseek.com/quick_start/pricing) para as tarifas atuais (a listagem cloud do Ollama para o deepseek-v4.1-flash mostra tarifas próprias por token). Uma configuração local não tem tarifa por token, mas custa hardware e energia elétrica. O principal motivo para rodar localmente é que a inferência fica no seu computador em vez de ir para a API em nuvem de um fornecedor (confira a telemetria das suas ferramentas), não que seja mais barato.',
          },
          {
            q: 'DeepSeek-V3, R1 e Qwen2.5-Coder ainda são atuais?',
            a: 'Não. São a geração anterior e aparecem apenas na seção de histórico. Os nomes de API deepseek-chat e deepseek-reasoner da DeepSeek (era V3/R1) estavam programados para ser desativados em 2026-07-24. As gerações abertas atuais são DeepSeek V4 / V4.1 e Qwen3.8; para o tamanho MoE 35B-A3B não encontramos um sucessor Qwen3.8 na listagem da Qwen no Hugging Face, por isso o Qwen3.6-35B-A3B é mostrado.',
          },
        ],
      },
